<section class="admin-panel" aria-labelledby="navigation-item-title"><header class="admin-panel__header"><div class="admin-panel__heading"><h2 class="admin-panel__title" id="navigation-item-title">Navigation item</h2></div></header><div class="admin-panel__body"><?php if ($errors !== []): ?><div class="admin-alert admin-alert--danger" role="alert"><?php foreach ($errors as $group): foreach ((array) $group as $error): ?><p><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endforeach; endforeach; ?></div><?php endif; ?><form class="admin-form" method="post" action="<?= htmlspecialchars($formAction, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="_token" value="<?= htmlspecialchars($csrfToken ?? '', ENT_QUOTES, 'UTF-8') ?>"><div class="admin-field"><label class="admin-field__label" for="label">Label</label><input id="label" name="label" required value="<?= htmlspecialchars((string) ($item['label'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></div><div class="admin-field"><label class="admin-field__label" for="parent_id">Parent item</label><select id="parent_id" name="parent_id"><option value="">Root item</option><?php foreach ($parents as $candidate): $candidateItem=$candidate['item']; ?><option value="<?= $candidateItem->id() ?>" <?= (string) ($item['parent_id'] ?? '') === (string) $candidateItem->id() ? 'selected' : '' ?>><?= str_repeat('— ', (int) $candidate['depth']) . htmlspecialchars($candidateItem->label(), ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><fieldset class="admin-fieldset"><legend>Target</legend><div class="admin-field"><label class="admin-field__label" for="target_mode">Target type</label><select id="target_mode" name="target_mode"><option value="custom" <?= ($item['target_mode'] ?? '') === 'custom' ? 'selected' : '' ?>>Custom URL</option><option value="provider" <?= ($item['target_mode'] ?? '') === 'provider' ? 'selected' : '' ?>>Content or Article Collection</option></select></div><div class="admin-field"><label class="admin-field__label" for="custom_url">Custom URL</label><input id="custom_url" name="custom_url" value="<?= htmlspecialchars((string) ($item['custom_url'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></div><div class="admin-field"><label class="admin-field__label" for="target_kind">Target kind</label><select id="target_kind" name="target_kind"><option value="content" <?= ($item['target_kind'] ?? '') === 'content' ? 'selected' : '' ?>>Content</option><option value="article_collection" <?= ($item['target_kind'] ?? '') === 'article_collection' ? 'selected' : '' ?>>Article Collection</option></select></div><div class="admin-field"><label class="admin-field__label" for="target_reference">Target reference</label><input id="target_reference" name="target_reference" value="<?= htmlspecialchars((string) ($item['target_reference'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"><p class="admin-field__help">Use a published Content slug, or articles for the Article Collection.</p></div></fieldset><label class="admin-check-option"><input type="checkbox" name="is_visible" value="1" <?= !empty($item['is_visible']) ? 'checked' : '' ?>> Visible</label><div class="admin-form__actions"><button class="admin-button admin-button--primary" type="submit">Save</button></div></form></div></section>
